export function TimelineView({
  title = "{{title}}",
  rangeLabel = "{{rangeLabel}}",
  density = "{{density}}",
  showLabels = {{showLabels}},
  accent = "{{accent}}",
}) {
  const compact = density === "Compact";
  const trackHeight = compact ? 40 : 60;
  const barTop = compact ? 5 : 10;
  const barHeight = compact ? 30 : 40;
  const bar = { position: "absolute", top: barTop, height: barHeight, borderRadius: 6, display: "flex", alignItems: "center", padding: "0 10px", fontWeight: 700, color: "#14351f", fontSize: 12, boxSizing: "border-box", overflow: "hidden", whiteSpace: "nowrap" };
  const phases = [
    { name: "Discovery", left: "2%", width: "26%", bg: accent },
    { name: "Build", left: "30%", width: "40%", bg: "#D9C8F0" },
    { name: "Launch", left: "72%", width: "26%", bg: "#F5C2E0" },
  ];
  return (
    <div style={{ font: "13px/1.3 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 480, padding: 18, borderRadius: 12, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 14 }}>
        <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>{title}</h3>
        <span style={{ fontSize: 12, color: "#24143099" }}>{rangeLabel}</span>
      </div>
      <div style={{ position: "relative", height: trackHeight, background: "#24143010", borderRadius: 8 }}>
        {phases.map((p) => (
          <span key={p.name} style={{ ...bar, left: p.left, width: p.width, background: p.bg }}>{showLabels && p.name}</span>
        ))}
      </div>
    </div>
  );
}
